function parseAvcPps(unit) {
  const fields=[],br=new BitReader(rbsp(unit.data,1));
  try { const id=br.ue(),spsId=br.ue(); addField(fields,"pic_parameter_set_id",id,"ue(v)");addField(fields,"seq_parameter_set_id",spsId,"ue(v)");const entropy=br.flag(),bottom=br.flag();addField(fields,"entropy_coding_mode_flag",entropy,"u(1)");addField(fields,"bottom_field_pic_order_in_frame_present_flag",bottom,"u(1)");const groups=br.ue();addField(fields,"num_slice_groups_minus1",groups,"ue(v)");if(groups>0)return{id,spsId,entropy,bottom,groups,fields};const l0=br.ue(),l1=br.ue();addField(fields,"num_ref_idx_l0_default_active_minus1",l0,"ue(v)");addField(fields,"num_ref_idx_l1_default_active_minus1",l1,"ue(v)");const weightedPred=br.flag(),weightedBi=br.u(2);addField(fields,"weighted_pred_flag",weightedPred,"u(1)");addField(fields,"weighted_bipred_idc",weightedBi,"u(2)");const initQp=br.se(),initQs=br.se(),chromaQp=br.se();addField(fields,"pic_init_qp_minus26",initQp,"se(v)");addField(fields,"pic_init_qs_minus26",initQs,"se(v)");addField(fields,"chroma_qp_index_offset",chromaQp,"se(v)");const deblock=br.flag(),constrained=br.flag(),redundant=br.flag();addField(fields,"deblocking_filter_control_present_flag",deblock,"u(1)");addField(fields,"constrained_intra_pred_flag",constrained,"u(1)");addField(fields,"redundant_pic_cnt_present_flag",redundant,"u(1)");return{id,spsId,entropy,bottom,l0,l1,weightedPred,weightedBi,initQp,deblock,redundant,fields}; } catch(e){return {fields,error:e.message};}
}

function parseAvcSlice(unit,spsMap,ppsMap) {
  const fields=[],br=new BitReader(rbsp(unit.data,1));
  try {
    const firstMb=br.ue(),rawType=br.ue(),sliceType=SLICE_NAMES[rawType%5]||"?",ppsId=br.ue(); addField(fields,"first_mb_in_slice",firstMb,"ue(v)");addField(fields,"slice_type",`${rawType} (${sliceType})`,"ue(v)");addField(fields,"pic_parameter_set_id",ppsId,"ue(v)");
    const pps=ppsMap.get(ppsId),sps=pps&&spsMap.get(pps.spsId); let frameNum=null,poc=null,idrId=null;
    if(sps && sps.log2Frame) { frameNum=br.u(sps.log2Frame);addField(fields,"frame_num",frameNum,`u(${sps.log2Frame})`); let fieldPic=0;if(!sps.frameOnly){fieldPic=br.flag();addField(fields,"field_pic_flag",fieldPic,"u(1)");if(fieldPic)addField(fields,"bottom_field_flag",br.flag(),"u(1)");} if(unit.nalType===5){idrId=br.ue();addField(fields,"idr_pic_id",idrId,"ue(v)");} if(sps.pocType===0){poc=br.u(sps.log2Poc);addField(fields,"pic_order_cnt_lsb",poc,`u(${sps.log2Poc})`);if(pps?.bottom&&!fieldPic)addField(fields,"delta_pic_order_cnt_bottom",br.se(),"se(v)");}else if(sps.pocType===1){addField(fields,"delta_pic_order_cnt[0]",br.se(),"se(v)");if(pps?.bottom&&!fieldPic)addField(fields,"delta_pic_order_cnt[1]",br.se(),"se(v)");}if(pps?.redundant)addField(fields,"redundant_pic_cnt",br.ue(),"ue(v)");if(sliceType==="B")addField(fields,"direct_spatial_mv_pred_flag",br.flag(),"u(1)");let refs0=(pps?.l0??0)+1,refs1=(pps?.l1??0)+1;if(["P","SP","B"].includes(sliceType)){const over=br.flag();addField(fields,"num_ref_idx_active_override_flag",over,"u(1)");if(over){refs0=br.ue()+1;addField(fields,"num_ref_idx_l0_active_minus1",refs0-1,"ue(v)");if(sliceType==="B"){refs1=br.ue()+1;addField(fields,"num_ref_idx_l1_active_minus1",refs1-1,"ue(v)");}}}if(!["I","SI"].includes(sliceType)){const mod=br.flag();addField(fields,"ref_pic_list_modification_flag_l0",mod,"u(1)");if(mod){for(let k=0;k<64;k++){const idc=br.ue();addField(fields,`modification_of_pic_nums_idc_l0[${k}]`,idc,"ue(v)");if(idc===3)break;if(idc===0||idc===1)addField(fields,`abs_diff_pic_num_minus1_l0[${k}]`,br.ue(),"ue(v)");else if(idc===2)addField(fields,`long_term_pic_num_l0[${k}]`,br.ue(),"ue(v)");}}if(sliceType==="B"){const mod1=br.flag();addField(fields,"ref_pic_list_modification_flag_l1",mod1,"u(1)");if(mod1){for(let k=0;k<64;k++){const idc=br.ue();addField(fields,`modification_of_pic_nums_idc_l1[${k}]`,idc,"ue(v)");if(idc===3)break;if(idc===0||idc===1)br.ue();else if(idc===2)br.ue();}}}}if((pps?.weightedPred&&["P","SP"].includes(sliceType))||(pps?.weightedBi===1&&sliceType==="B")){addField(fields,"luma_log2_weight_denom",br.ue(),"ue(v)");if(sps.chroma)addField(fields,"chroma_log2_weight_denom",br.ue(),"ue(v)");const lists=sliceType==="B"?[[0,refs0],[1,refs1]]:[[0,refs0]];for(const[list,count]of lists)for(let j=0;j<count;j++){const lw=br.flag();addField(fields,`luma_weight_l${list}_flag[${j}]`,lw,"u(1)");if(lw){addField(fields,`luma_weight_l${list}[${j}]`,br.se(),"se(v)");addField(fields,`luma_offset_l${list}[${j}]`,br.se(),"se(v)");}if(sps.chroma){const cw=br.flag();addField(fields,`chroma_weight_l${list}_flag[${j}]`,cw,"u(1)");if(cw)for(let c=0;c<2;c++){addField(fields,`chroma_weight_l${list}[${j}][${c}]`,br.se(),"se(v)");addField(fields,`chroma_offset_l${list}[${j}][${c}]`,br.se(),"se(v)");}}}}if(unit.refIdc!==0){if(unit.nalType===5){addField(fields,"no_output_of_prior_pics_flag",br.flag(),"u(1)");addField(fields,"long_term_reference_flag",br.flag(),"u(1)");}else{const adaptive=br.flag();addField(fields,"adaptive_ref_pic_marking_mode_flag",adaptive,"u(1)");if(adaptive)for(let k=0;k<64;k++){const mmco=br.ue();addField(fields,`memory_management_control_operation[${k}]`,mmco,"ue(v)");if(mmco===0)break;if(mmco===1||mmco===3)addField(fields,`difference_of_pic_nums_minus1[${k}]`,br.ue(),"ue(v)");if(mmco===2)addField(fields,`long_term_pic_num[${k}]`,br.ue(),"ue(v)");if(mmco===3||mmco===6)addField(fields,`long_term_frame_idx[${k}]`,br.ue(),"ue(v)");if(mmco===4)addField(fields,`max_long_term_frame_idx_plus1[${k}]`,br.ue(),"ue(v)");}}}if(pps?.entropy&&!["I","SI"].includes(sliceType))addField(fields,"cabac_init_idc",br.ue(),"ue(v)");const qp=br.se();addField(fields,"slice_qp_delta",qp,"se(v)");if(sliceType==="SP"){addField(fields,"sp_for_switch_flag",br.flag(),"u(1)");addField(fields,"slice_qs_delta",br.se(),"se(v)");}else if(sliceType==="SI")addField(fields,"slice_qs_delta",br.se(),"se(v)");if(pps?.deblock){const disable=br.ue();addField(fields,"disable_deblocking_filter_idc",disable,"ue(v)");if(disable!==1){addField(fields,"slice_alpha_c0_offset_div2",br.se(),"se(v)");addField(fields,"slice_beta_offset_div2",br.se(),"se(v)");}} }
    return {firstMb,rawType,sliceType,ppsId,frameNum,poc,idrId,fields};
  } catch(e){return {sliceType:"?",fields,error:e.message};}
}

