  const cu=frame.codingUnits,cached=previewManager?.cache.get(frame.index),regions=cu?.regions||[];
  const aspect=state.model.primarySps?.width&&state.model.primarySps?.height?`${state.model.primarySps.width} / ${state.model.primarySps.height}`:"16 / 9";
  tab.innerHTML=`<div class="visual-toolbar"><span>Frame ${String(frame.index).padStart(4,"0")} · ${esc(frame.displayType||frame.type)}</span><label><input id="toggleUnitGrid" type="checkbox" checked /> 网格</label><label><input id="toggleSliceFill" type="checkbox" checked /> Slice 区域</label></div><div class="frame-visual-stage" style="aspect-ratio:${aspect}"><img id="framePreviewImage" data-frame="${frame.index}" src="${cached||""}" ${cached?"":"hidden"} alt="Frame ${frame.index} 画面预览" /><canvas id="unitMapCanvas" aria-label="宏块与 Slice 分布图"></canvas><div class="preview-message" id="framePreviewMessage" ${cached?"hidden":""}><span class="preview-spinner">◌</span><strong>正在按需生成画面预览</strong><small>从最近的随机访问点或 Recovery Point 分批解码</small></div></div><div class="unit-hover" id="unitHover">移动到网格可查看${cu?.kind||"编码单元"}地址</div>${cu?`<div class="unit-stats">${[["单元类型",`${cu.kind} · ${cu.unitSize}×${cu.unitSize}`],["网格",`${cu.cols} 列 × ${cu.rows} 行`],["总数",cu.total.toLocaleString()],["Slice 区域",regions.length],["覆盖",`${cu.covered.toLocaleString()} / ${cu.total.toLocaleString()}`],["边界可信度",cu.preciseBoundaries?"由 Slice 首地址精确推导":"存在 FMO，需按映射表解释"]].map(v=>`<div><label>${v[0]}</label><strong>${v[1]}</strong></div>`).join("")}</div><div class="unit-region-list">${regions.map((r,i)=>`<div class="unit-region type-${esc(r.type)}"><i></i><div><strong>Slice #${r.sliceIndex} · ${esc(r.type)}</strong><small>地址 ${r.start}–${Math.max(r.start,r.end-1)} · ${r.count.toLocaleString()} ${cu.kind}${r.qp==null?"":` · Slice QP ${r.qp}`}</small></div><span>行 ${r.firstRow}–${r.lastRow}</span></div>`).join("")}</div><p class="summary-note">颜色表示 Slice Header 推导出的覆盖范围和 Slice 类型。单个宏块的真实 mb_type、运动矢量、残差和逐块 QP 需要完整 CABAC/CAVLC 熵解码；这里不会用估算值冒充解析结果。</p>`:`<p class="summary-note">当前参数集不足，暂时无法建立宏块 / CTU 网格。</p>`}`;
  if(cu){drawCodingUnitMap(frame,true,true);$("#toggleUnitGrid").onchange=e=>drawCodingUnitMap(frame,e.target.checked,$("#toggleSliceFill").checked);$("#toggleSliceFill").onchange=e=>drawCodingUnitMap(frame,$("#toggleUnitGrid").checked,e.target.checked);}
  previewManager?.request(frame.index,true);
