function drawCodingUnitMap(frame,showGrid=true,showFill=true){
  const canvas=$("#unitMapCanvas"),cu=frame.codingUnits;if(!canvas||!cu)return;const s=state.model.primarySps,width=720,height=Math.max(180,Math.round(width*s.height/s.width)),dpr=Math.min(2,window.devicePixelRatio||1);canvas.width=width*dpr;canvas.height=height*dpr;const ctx=canvas.getContext("2d");ctx.scale(dpr,dpr);ctx.clearRect(0,0,width,height);const cw=width/cu.cols,ch=height/cu.rows,colors={I:"rgba(244,162,97,.30)",P:"rgba(88,166,255,.27)",B:"rgba(155,135,245,.28)",VCL:"rgba(25,194,201,.25)",SP:"rgba(66,211,146,.25)",SI:"rgba(244,162,97,.25)"};
  if(showFill)cu.regions.forEach(r=>{ctx.fillStyle=colors[r.type]||"rgba(25,194,201,.25)";for(let address=r.start;address<r.end;){const row=Math.floor(address/cu.cols),rowEnd=Math.min(r.end,(row+1)*cu.cols),col=address%cu.cols;ctx.fillRect(col*cw,row*ch,(rowEnd-address)*cw,ch);address=rowEnd;}});
  const first=cu.regions[0]?.start||0;if(first>0){ctx.fillStyle="rgba(255,107,107,.22)";for(let a=0;a<first;){const row=Math.floor(a/cu.cols),rowEnd=Math.min(first,(row+1)*cu.cols),col=a%cu.cols;ctx.fillRect(col*cw,row*ch,(rowEnd-a)*cw,ch);a=rowEnd;}}
  ctx.strokeStyle="rgba(255,255,255,.2)";ctx.lineWidth=.6;cu.regions.forEach(r=>{const y=r.start/cu.cols*ch;ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(width,y);ctx.stroke();});
  if(showGrid){const step=Math.max(1,Math.ceil(2/Math.min(cw,ch)));ctx.strokeStyle="rgba(135,156,176,.18)";ctx.lineWidth=.45;ctx.beginPath();for(let x=0;x<=cu.cols;x+=step){ctx.moveTo(x*cw,0);ctx.lineTo(x*cw,height);}for(let y=0;y<=cu.rows;y+=step){ctx.moveTo(0,y*ch);ctx.lineTo(width,y*ch);}ctx.stroke();}
  canvas.onmousemove=e=>{const rect=canvas.getBoundingClientRect(),col=Math.min(cu.cols-1,Math.floor((e.clientX-rect.left)/rect.width*cu.cols)),row=Math.min(cu.rows-1,Math.floor((e.clientY-rect.top)/rect.height*cu.rows)),address=row*cu.cols+col,region=cu.regions.find(r=>address>=r.start&&address<r.end),el=$("#unitHover");el.innerHTML=`<b>${cu.kind} ${address}</b><span>列 ${col} · 行 ${row} · 像素 (${col*cu.unitSize}, ${row*cu.unitSize})</span><span>${region?`Slice #${region.sliceIndex} · ${esc(region.type)}${region.qp==null?"":` · Slice QP ${region.qp}`}`:"起始区域未包含在当前帧 Slice 中"}</span>`;};
}
function currentTimelineFrame(){if(state.mode==="frames")return state.model.frames[state.selected]?.index??0;const nal=state.model.nals[state.selected];return state.model.frames.find(f=>f.nals.includes(nal))?.index??0;}
function drawReferenceOverlay(frame,start,end){const svg=$("#referenceOverlay");if(!svg||!frame)return;const span=Math.max(1,end-start),x=i=>((i-start+.5)/span)*1000,selectedX=x(frame.index),paths=[];if(frame.externalReferences?.length)paths.push(`<path class="missing-path" marker-end="url(#arrowMissing)" d="M 0 25 Q ${selectedX/2} 2 ${selectedX} 25"/>`);(frame.references||[]).forEach((r,i)=>{if(r.frame>=start&&r.frame<end)paths.push(`<path class="incoming-path" marker-end="url(#arrowIn)" d="M ${x(r.frame)} 25 Q ${(x(r.frame)+selectedX)/2} ${2+i*4} ${selectedX} 25"/>`);});(frame.referencedBy||[]).slice(0,8).forEach((r,i)=>{if(r.frame>=start&&r.frame<end)paths.push(`<path class="outgoing-path" marker-end="url(#arrowOut)" d="M ${selectedX} 27 Q ${(selectedX+x(r.frame))/2} ${5+i*2} ${x(r.frame)} 27"/>`);});svg.innerHTML=`<defs><marker id="arrowIn" viewBox="0 0 6 6" refX="5" refY="3" markerWidth="5" markerHeight="5" orient="auto"><path d="M0,0 L6,3 L0,6 Z" fill="#19c2c9"/></marker><marker id="arrowOut" viewBox="0 0 6 6" refX="5" refY="3" markerWidth="5" markerHeight="5" orient="auto"><path d="M0,0 L6,3 L0,6 Z" fill="#9b87f5"/></marker><marker id="arrowMissing" viewBox="0 0 6 6" refX="5" refY="3" markerWidth="5" markerHeight="5" orient="auto"><path d="M0,0 L6,3 L0,6 Z" fill="#ff6b6b"/></marker></defs>${paths.join("")}`;}
function renderTimeline(){const frames=state.model.frames;if(!frames.length)return;const selected=currentTimelineFrame(),windowSize=Math.min(frames.length,Math.max(30,Math.floor(120/state.zoom))),start=Math.max(0,Math.min(frames.length-windowSize,selected-Math.floor(windowSize/2))),end=start+windowSize,shown=frames.slice(start,end),max=Math.max(...shown.map(x=>x.size),1),track=$("#timelineTrack");track.innerHTML=`<svg class="reference-overlay" id="referenceOverlay" viewBox="0 0 1000 68" preserveAspectRatio="none"></svg>`+shown.map(x=>`<div class="frame-block ${x.type} ${x.recoveryPoints?.length?"recovery":""} ${x.index===selected?"selected":""}" data-frame="${x.index}" style="height:${8+32*Math.sqrt(x.size/max)}px" title="Frame ${x.index} · ${x.type} · ${x.references?.map(r=>`${r.list}←F${r.frame}`).join(", ")|| (x.externalReferences?.length?"缺失文件外参考":"无帧间参考")}${x.recoveryPoints?.length?` · Recovery +${x.recoveryPoints[0].recoveryFrameCnt}`:""}"></div>`).join("");$$('.frame-block').forEach(el=>el.onclick=()=>{state.mode="frames";syncMode();selectItem(+el.dataset.frame);});const selectedFrame=frames[selected],incoming=selectedFrame.externalReferences?.length?"文件外参考缺失":selectedFrame.references?.length?selectedFrame.references.map(r=>`${r.list} ← F${r.frame}`).join(" · "):"无帧间参考",outgoing=selectedFrame.referencedBy?.length?`→ ${selectedFrame.referencedBy.slice(0,3).map(r=>`F${r.frame}`).join(", ")}`:"";$("#referenceSummary").textContent=`F${selected} · ${incoming} ${outgoing}`;$("#timelineRange").textContent=`${fmtTime(frames[start]?.pts||0)} — ${fmtTime((frames[end-1]?.pts||0)+1/state.model.fps)}`;$("#timelineRuler").innerHTML=Array.from({length:9},(_,i)=>{const fi=Math.min(end-1,start+Math.floor((windowSize-1)*i/8));return`<span class="tick" style="left:${i*12.5}%"><label>F${fi} · ${fmtTime(frames[fi]?.pts||0,false)}</label></span>`;}).join("");$("#zoomLabel").textContent=`${Math.round(state.zoom*100)}%`;drawReferenceOverlay(selectedFrame,start,end);}

const renderTimelineCore=renderTimeline;
renderTimeline=function(){renderTimelineCore();$$('.frame-block').forEach(el=>{const f=state.model.frames[+el.dataset.frame];if(!f)return;if(f.isRandomAccess){el.classList.remove("I");el.classList.add(state.model.codec==="avc"?"IDR":"IRAP");}if(f.isSliced)el.classList.add("sliced");if(f.isTruncatedStart)el.classList.add("truncated");el.title+=` · ${f.structureLabel}`;});};

function syncMode(){$$('#modeSegment button').forEach(b=>b.classList.toggle('active',b.dataset.mode===state.mode));state.selected=0;renderTable();selectItem(0,false);}
async function loadFile(file){try{toast(`正在解析 ${file.name}…`);const bytes=new Uint8Array(await file.arrayBuffer());if(!bytes.length)throw Error("文件为空");const model=parseStream(bytes,file.name);if(!model.nals.length)throw Error("没有识别到 NAL 单元");previewManager?.dispose();state.model=model;previewManager=new FramePreviewManager(model);state.selected=0;state.filter="ALL";state.query="";$("#searchInput").value="";$$('.filter-button').forEach(b=>b.classList.toggle('active',b.dataset.filter==="ALL"));renderAll();toast(`解析完成：${model.frames.length} 帧，${model.nals.length} 个 NAL 单元`);}catch(e){toast(`解析失败：${e.message}`,4000);}}
let toastTimer;function toast(msg,delay=2400){const el=$("#toast");el.textContent=msg;el.classList.add("show");clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove("show"),delay);}

function bind(){
  $("#openButton").onclick=()=>$("#fileInput").click();$("#fileInput").onchange=e=>e.target.files[0]&&loadFile(e.target.files[0]);
  $$('#modeSegment button').forEach(b=>b.onclick=()=>{state.mode=b.dataset.mode;syncMode();});
  $$('.filter-button').forEach(b=>b.onclick=()=>{state.filter=b.dataset.filter;$$('.filter-button').forEach(x=>x.classList.toggle('active',x===b));renderTable();});
  $("#searchInput").oninput=e=>{state.query=e.target.value;renderTable();};
  $$('.tabs button').forEach(b=>b.onclick=()=>{$$('.tabs button').forEach(x=>x.classList.toggle('active',x===b));$$('.tab-content').forEach(x=>x.classList.remove('active'));$(`#${b.dataset.tab}Tab`).classList.add('active');});
  $("#themeButton").onclick=()=>document.body.classList.toggle("compact");$("#helpButton").onclick=()=>$("#helpDialog").showModal();$("#closeHelp").onclick=()=>$("#helpDialog").close();
  $("#zoomIn").onclick=()=>{state.zoom=Math.min(4,state.zoom+.25);renderTimeline();};$("#zoomOut").onclick=()=>{state.zoom=Math.max(.5,state.zoom-.25);renderTimeline();};$("#fitTimeline").onclick=()=>{state.zoom=1;renderTimeline();};
  window.addEventListener("keydown",e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==="o"){e.preventDefault();$("#fileInput").click();}else if(e.key==="/"&&document.activeElement!==$("#searchInput")){e.preventDefault();$("#searchInput").focus();}else if(["ArrowDown","ArrowUp"].includes(e.key)&&document.activeElement.tagName!=="INPUT"){e.preventDefault();selectItem(state.selected+(e.key==="ArrowDown"?1:-1));}else if(["1","2","3","4","5","6"].includes(e.key)&&document.activeElement.tagName!=="INPUT"){$$('.tabs button')[+e.key-1]?.click();}});
  let dragDepth=0;window.addEventListener("dragenter",e=>{e.preventDefault();dragDepth++;$("#dropOverlay").classList.add("visible");});window.addEventListener("dragleave",e=>{e.preventDefault();if(--dragDepth<=0){dragDepth=0;$("#dropOverlay").classList.remove("visible");}});window.addEventListener("dragover",e=>e.preventDefault());window.addEventListener("drop",e=>{e.preventDefault();dragDepth=0;$("#dropOverlay").classList.remove("visible");e.dataTransfer.files[0]&&loadFile(e.dataTransfer.files[0]);});
  $$('.nav-button[data-view]').forEach(b=>b.onclick=()=>{$$('.nav-button[data-view]').forEach(x=>x.classList.toggle('active',x===b));const view=b.dataset.view;if(view==="frames"){state.mode="frames";syncMode();}else if(view==="params"){state.mode="nals";state.filter="PARAM";$$('.filter-button').forEach(x=>x.classList.toggle('active',x.dataset.filter==="PARAM"));syncMode();renderTable();}else if(view==="stats")toast("统计视图已汇总在顶部指标和帧时间线中");else{state.mode="nals";state.filter="ALL";syncMode();}});
}

